using System;
using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "Player Dice", menuName = "Data/Battle/Dice System/Player Dice")]
public class PlayerDice : Dice
{
	[Header("Player Dice Data")]
	public Character Character;

	public List<int> ChapterMute = new List<int>();

	public bool CantBePickedAsReward;

	[SerializeField]
	private CompendiumItemState compendiumItemState;

	public bool Tutorial;

	[NonSerialized]
	[ShowNonSerializedField]
	public bool DiceJustPlayed;

	[NonSerialized]
	[ShowNonSerializedField]
	public bool Magnetized;

	[NonSerialized]
	[ShowNonSerializedField]
	public bool MuteForMod;

	public CompendiumItemState CompendiumItemState => compendiumItemState;

	public string GetChapterAppearanceText()
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetChapterAppearanceText(ChapterMute);
	}

	public void SetCompendiumItemState(CompendiumItemState compendiumItemState)
	{
		this.compendiumItemState = compendiumItemState;
	}
}
